package com.johnny.hotel.cashier;import com.johnny.hotel.cashier.CashierModels.*;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.exception.BusinessException;import lombok.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.*;
@Service@RequiredArgsConstructor public class CashierPostingService{private final CashierMapper db;private final BusinessDateService dates;private final Clock clock;
 @Transactional(propagation=Propagation.MANDATORY)public Movement post(Long operator,String direction,String type,BigDecimal amount,String currency,String sourceType,Long sourceId,String requestKey,String note){var old=db.movementBySource(sourceType,sourceId);if(old!=null){if(old.getAmount().compareTo(amount)!=0||!old.getDirection().equals(direction))throw new BusinessException("Cash source idempotency conflict");return old;}var shift=db.activeByOperator(operator);if(shift==null||!"ACTIVE".equals(shift.getStatus()))throw new BusinessException("Operator has no active cashier shift");var drawer=db.lockDrawer(shift.getDrawerId());if(drawer==null||!shift.getId().equals(drawer.getActiveShiftId())||!drawer.getCurrency().equals(currency))throw new BusinessException("Active cash drawer mismatch");var m=Movement.builder().drawerId(drawer.getId()).shiftId(shift.getId()).direction(direction).movementType(type).amount(amount.setScale(2)).currency(currency).sourceType(sourceType).sourceId(sourceId).requestKey(requestKey).operatorUserId(operator).occurredAt(LocalDateTime.now(clock)).postingBusinessDate(dates.postingDate()).note(note).build();if(db.insertMovement(m)!=1)throw new BusinessException("Cash movement failed");return m;}
}
